import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../contexts/AuthContext'

// Shared Mock Data for Admin
const API_URL = import.meta.env.VITE_API_URL || '/api/v1'

export default function AdminPage() {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'dashboard' | 'problems' | 'users' | 'settings'>('dashboard')
  const [showModal, setShowModal] = useState(false)
  const [editingId, setEditingId] = useState<number | null>(null)
  const [stats, setStats] = useState<any>(null)
  const [problems, setProblems] = useState<any[]>([])
  
  // Form state
  const [newTitle, setNewTitle] = useState('')
  const [newDifficulty, setNewDifficulty] = useState('Easy')
  const [newDesc, setNewDesc] = useState('')
  const [newPublished, setNewPublished] = useState(false)
  const [newTestCases, setNewTestCases] = useState<{input: string, expectedOutput: string, isHidden: boolean}[]>([])
  const [newTemplates, setNewTemplates] = useState<{ python: string; javascript: string; cpp: string; java: string }>({ python: '', javascript: '', cpp: '', java: '' })

  const openCreateModal = () => {
    setEditingId(null)
    setNewTitle('')
    setNewDifficulty('Easy')
    setNewDesc('')
    setNewPublished(false)
    setNewTestCases([{ input: '', expectedOutput: '', isHidden: false }])
    setNewTemplates({ python: '', javascript: '', cpp: '', java: '' })
    setShowModal(true)
  }

  const openEditModal = (p: any) => {
    setEditingId(p.id)
    setNewTitle(p.title)
    setNewDifficulty(p.difficulty)
    setNewDesc(p.description)
    setNewPublished(p.published)
    setNewTestCases(p.testCases && p.testCases.length > 0 ? p.testCases : [{ input: '', expectedOutput: '', isHidden: false }])
    setNewTemplates({
      python: p.templates?.python || '',
      javascript: p.templates?.javascript || '',
      cpp: p.templates?.cpp || '',
      java: p.templates?.java || ''
    })
    setShowModal(true)
  }

  useEffect(() => {
    if (user) {
      user.getIdToken().then(token => {
        // Fetch Stats
        fetch(`${API_URL}/admin/stats`, { headers: { 'Authorization': `Bearer ${token}` } })
          .then(res => res.json())
          .then(data => setStats(data))
          .catch(console.error)

        // Fetch Problems
        fetch(`${API_URL}/admin/problems`, { headers: { 'Authorization': `Bearer ${token}` } })
          .then(res => res.json())
          .then(data => setProblems(data))
          .catch(console.error)
      })
    }
  }, [user, activeTab])

  const handleSaveProblem = async () => {
    try {
      const token = await user?.getIdToken()
      const method = editingId ? 'PUT' : 'POST'
      const url = editingId ? `${API_URL}/admin/problems/${editingId}` : `${API_URL}/admin/problems`

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({
          title: newTitle,
          difficulty: newDifficulty,
          description: newDesc,
          published: newPublished,
          tags: [],
          testCases: newTestCases,
          templates: newTemplates
        })
      })
      if (res.ok) {
        setShowModal(false)
        const data = await res.json()
        
        // Refresh problems to get updated data including testCases
        fetch(`${API_URL}/admin/problems`, { headers: { 'Authorization': `Bearer ${token}` } })
          .then(r => r.json())
          .then(d => setProblems(d))
      } else {
        alert('Failed to save problem (Must be Admin/Problem Setter)')
      }
    } catch (e) {
      console.error(e)
    }
  }

  // In a real app, this route should be protected by an AdminRoute wrapper.
  // For the demo, we allow anyone logged in to see the dashboard UI!
  if (!user) {
    return (
      <div style={{ color: 'white', padding: 40, textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100vh', background: 'var(--color-ink)' }}>
        <div style={{ fontSize: '1.5rem', marginBottom: 16 }}>Access Denied</div>
        <div style={{ color: 'var(--color-text-secondary)', marginBottom: 24 }}>Please sign in to view the Admin Dashboard.</div>
        <Link to="/signin" style={{ background: '#3B82F6', color: 'white', padding: '10px 20px', borderRadius: 8, textDecoration: 'none', fontWeight: 600 }}>Go to Sign In</Link>
      </div>
    )
  }

  return (
    <div style={{ minHeight: '100vh', background: 'var(--color-ink)', display: 'flex' }}>
      
      {/* ── SIDEBAR ── */}
      <div style={{ width: 260, borderRight: '1px solid var(--color-border)', background: 'var(--color-surface-1)', padding: '24px 0', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '0 24px', marginBottom: 32 }}>
          <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 800, fontSize: '1.25rem', color: 'white', textDecoration: 'none', letterSpacing: '-0.03em' }}>
            <div style={{ width: 28, height: 28, borderRadius: 7, background: 'linear-gradient(135deg,rgba(59,130,246,0.3),rgba(20,184,166,0.2))', border: '1px solid rgba(59,130,246,0.3)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <svg width="16" height="16" viewBox="0 0 18 18" fill="none"><path d="M5 9l3 3 6-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
            </div>
            Code<span style={{ color: '#60A5FA' }}>Admin</span>
          </Link>
        </div>

        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 4, padding: '0 12px' }}>
          {[
            { id: 'dashboard', label: 'Dashboard', icon: 'M4 6a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6zM14 6a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2h-2a2 2 0 0 1-2-2V6zM4 16a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-2zM14 16a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2h-2a2 2 0 0 1-2-2v-2z' },
            { id: 'problems', label: 'Manage Problems', icon: 'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z' },
            { id: 'users', label: 'Users & Roles', icon: 'M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2' },
            { id: 'settings', label: 'Platform Settings', icon: 'M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z' }
          ].map(t => (
            <button
              key={t.id}
              onClick={() => setActiveTab(t.id as any)}
              style={{
                display: 'flex', alignItems: 'center', gap: 12, padding: '10px 16px', borderRadius: 8, border: 'none',
                background: activeTab === t.id ? 'rgba(59,130,246,0.1)' : 'transparent',
                color: activeTab === t.id ? '#60A5FA' : 'var(--color-text-secondary)',
                fontSize: '0.9rem', fontWeight: activeTab === t.id ? 600 : 500, cursor: 'pointer',
                textAlign: 'left', transition: 'all 0.2s'
              }}
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d={t.icon}/></svg>
              {t.label}
            </button>
          ))}
        </div>
        
        <div style={{ padding: '0 24px', color: 'var(--color-text-tertiary)', fontSize: '0.75rem' }}>
          Logged in as<br/>
          <span style={{ color: 'white', fontWeight: 600 }}>{user.email}</span>
        </div>
      </div>

      {/* ── MAIN CONTENT ── */}
      <div style={{ flex: 1, padding: '48px 64px', overflowY: 'auto' }}>
        
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 40 }}>
          <div>
            <h1 style={{ color: 'white', fontSize: '2rem', marginBottom: 8, letterSpacing: '-0.02em' }}>
              {activeTab === 'dashboard' ? 'Platform Overview' : activeTab === 'problems' ? 'Problem Bank' : activeTab === 'users' ? 'User Management' : 'Settings'}
            </h1>
            <p style={{ color: 'var(--color-text-secondary)' }}>
              {activeTab === 'dashboard' ? 'Monitor system health and recent activity.' : 'Manage and review algorithmic content.'}
            </p>
          </div>
          
          {activeTab === 'problems' && (
            <button 
              onClick={openCreateModal}
              style={{ background: '#3B82F6', color: 'white', border: 'none', padding: '10px 20px', borderRadius: 8, fontWeight: 600, fontSize: '0.9rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8, boxShadow: '0 4px 14px rgba(59,130,246,0.4)' }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
              Create Problem
            </button>
          )}
        </div>

        {activeTab === 'dashboard' && (
          <>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 24, marginBottom: 48 }}>
              <div style={{ background: 'var(--color-surface-1)', padding: 24, borderRadius: 16, border: '1px solid var(--color-border)' }}>
                <div style={{ color: 'var(--color-text-tertiary)', fontSize: '0.85rem', marginBottom: 8 }}>Total Submissions</div>
                <div style={{ color: 'white', fontSize: '2rem', fontWeight: 700, letterSpacing: '-0.03em' }}>{stats?.totalSubmissions || 0}</div>
              </div>
              <div style={{ background: 'var(--color-surface-1)', padding: 24, borderRadius: 16, border: '1px solid var(--color-border)' }}>
                <div style={{ color: 'var(--color-text-tertiary)', fontSize: '0.85rem', marginBottom: 8 }}>Active Users</div>
                <div style={{ color: 'white', fontSize: '2rem', fontWeight: 700, letterSpacing: '-0.03em' }}>{stats?.activeUsers || 0}</div>
              </div>
              <div style={{ background: 'var(--color-surface-1)', padding: 24, borderRadius: 16, border: '1px solid var(--color-border)' }}>
                <div style={{ color: 'var(--color-text-tertiary)', fontSize: '0.85rem', marginBottom: 8 }}>Avg. Execution Time</div>
                <div style={{ color: 'white', fontSize: '2rem', fontWeight: 700, letterSpacing: '-0.03em' }}>{stats?.avgExecutionTime || 0}ms</div>
              </div>
              <div style={{ background: 'var(--color-surface-1)', padding: 24, borderRadius: 16, border: '1px solid var(--color-border)' }}>
                <div style={{ color: 'var(--color-text-tertiary)', fontSize: '0.85rem', marginBottom: 8 }}>Pending Drafts</div>
                <div style={{ color: 'white', fontSize: '2rem', fontWeight: 700, letterSpacing: '-0.03em' }}>{stats?.pendingDrafts || 0}</div>
              </div>
            </div>

            <h2 style={{ color: 'white', fontSize: '1.25rem', marginBottom: 16 }}>Recent Submissions</h2>
            <div style={{ background: 'var(--color-surface-1)', borderRadius: 12, border: '1px solid var(--color-border)', overflow: 'hidden' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid var(--color-border)', color: 'var(--color-text-secondary)', fontSize: '0.8rem' }}>
                    <th style={{ padding: '12px 24px', fontWeight: 500 }}>User</th>
                    <th style={{ padding: '12px 24px', fontWeight: 500 }}>Problem</th>
                    <th style={{ padding: '12px 24px', fontWeight: 500 }}>Status</th>
                    <th style={{ padding: '12px 24px', fontWeight: 500 }}>Time</th>
                  </tr>
                </thead>
                <tbody>
                  {[1, 2, 3, 4, 5].map(i => (
                    <tr key={i} style={{ borderBottom: '1px solid var(--color-border)', color: 'white', fontSize: '0.9rem' }}>
                      <td style={{ padding: '16px 24px' }}>user{i}@example.com</td>
                      <td style={{ padding: '16px 24px', color: '#60A5FA' }}>Two Sum</td>
                      <td style={{ padding: '16px 24px' }}>
                        <span style={{ color: i % 2 === 0 ? '#10B981' : '#EF4444', background: i % 2 === 0 ? 'rgba(16,185,129,0.1)' : 'rgba(239,68,68,0.1)', padding: '2px 8px', borderRadius: 4, fontSize: '0.75rem' }}>
                          {i % 2 === 0 ? 'Accepted' : 'Wrong Answer'}
                        </span>
                      </td>
                      <td style={{ padding: '16px 24px', color: 'var(--color-text-tertiary)' }}>{i * 12} mins ago</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {activeTab === 'problems' && (
          <div style={{ background: 'var(--color-surface-1)', borderRadius: 12, border: '1px solid var(--color-border)', overflow: 'hidden' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ borderBottom: '1px solid var(--color-border)', color: 'var(--color-text-secondary)', fontSize: '0.8rem' }}>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>ID</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Title</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Difficulty</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Status</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {problems.map(p => (
                  <tr key={p.id} style={{ borderBottom: '1px solid var(--color-border)', color: 'white', fontSize: '0.9rem' }}>
                    <td style={{ padding: '16px 24px', color: 'var(--color-text-tertiary)' }}>{p.id}</td>
                    <td style={{ padding: '16px 24px', fontWeight: 500 }}>{p.title}</td>
                    <td style={{ padding: '16px 24px' }}>{p.difficulty}</td>
                    <td style={{ padding: '16px 24px' }}>
                      <span style={{ color: p.published ? '#10B981' : '#F59E0B', background: p.published ? 'rgba(16,185,129,0.1)' : 'rgba(245,158,11,0.1)', padding: '2px 8px', borderRadius: 4, fontSize: '0.75rem' }}>
                        {p.published ? 'Published' : 'Draft'}
                      </span>
                    </td>
                    <td style={{ padding: '16px 24px' }}>
                      <button onClick={() => openEditModal(p)} style={{ background: 'none', border: '1px solid rgba(255,255,255,0.2)', color: 'white', padding: '4px 12px', borderRadius: 6, cursor: 'pointer' }}>Edit</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

      </div>

      {/* CREATE / EDIT MODAL */}
      {showModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: 20 }}>
          <div style={{ background: 'var(--color-surface-1)', padding: 32, borderRadius: 16, width: '100%', maxWidth: 800, maxHeight: '90vh', overflowY: 'auto', border: '1px solid var(--color-border)' }}>
            <h2 style={{ color: 'white', marginBottom: 24 }}>{editingId ? 'Edit Problem' : 'Create New Problem'}</h2>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <div style={{ display: 'flex', gap: 16 }}>
                <input value={newTitle} onChange={e => setNewTitle(e.target.value)} placeholder="Problem Title" style={{ flex: 2, padding: '12px 16px', borderRadius: 8, background: 'rgba(0,0,0,0.2)', border: '1px solid var(--color-border)', color: 'white' }} />
                <select value={newDifficulty} onChange={e => setNewDifficulty(e.target.value)} style={{ flex: 1, padding: '12px 16px', borderRadius: 8, background: 'rgba(0,0,0,0.2)', border: '1px solid var(--color-border)', color: 'white' }}>
                  <option>Easy</option>
                  <option>Medium</option>
                  <option>Hard</option>
                </select>
              </div>
              
              <textarea value={newDesc} onChange={e => setNewDesc(e.target.value)} placeholder="Markdown Description..." rows={6} style={{ width: '100%', padding: '12px 16px', borderRadius: 8, background: 'rgba(0,0,0,0.2)', border: '1px solid var(--color-border)', color: 'white', resize: 'vertical' }} />
              
              <label style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'white', cursor: 'pointer' }}>
                <input type="checkbox" checked={newPublished} onChange={e => setNewPublished(e.target.checked)} style={{ width: 16, height: 16 }} />
                Publish immediately (Visible to users)
              </label>

              <div style={{ borderTop: '1px solid var(--color-border)', margin: '12px 0' }} />
              
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h3 style={{ color: 'white', margin: 0 }}>Test Cases</h3>
                <button onClick={() => setNewTestCases([...newTestCases, { input: '', expectedOutput: '', isHidden: false }])} style={{ background: 'rgba(16,185,129,0.15)', color: '#34D399', border: '1px solid rgba(16,185,129,0.3)', padding: '4px 12px', borderRadius: 6, cursor: 'pointer', fontSize: '0.8rem' }}>+ Add Case</button>
              </div>
              
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                {newTestCases.map((tc, idx) => (
                  <div key={idx} style={{ background: 'rgba(0,0,0,0.15)', padding: 16, borderRadius: 8, border: '1px solid var(--color-border)', display: 'flex', flexDirection: 'column', gap: 8 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', color: 'var(--color-text-secondary)', fontSize: '0.8rem' }}>
                      <span>Case {idx + 1}</span>
                      <button onClick={() => setNewTestCases(newTestCases.filter((_, i) => i !== idx))} style={{ background: 'none', border: 'none', color: '#EF4444', cursor: 'pointer', fontSize: '0.75rem' }}>Remove</button>
                    </div>
                    <textarea value={tc.input} onChange={e => { const nc = [...newTestCases]; nc[idx].input = e.target.value; setNewTestCases(nc) }} placeholder="Input (e.g. 1\n2\n3)" rows={2} style={{ width: '100%', padding: '8px 12px', borderRadius: 4, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: 'white', fontFamily: 'monospace', fontSize: '0.85rem' }} />
                    <textarea value={tc.expectedOutput} onChange={e => { const nc = [...newTestCases]; nc[idx].expectedOutput = e.target.value; setNewTestCases(nc) }} placeholder="Expected Output" rows={2} style={{ width: '100%', padding: '8px 12px', borderRadius: 4, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: 'white', fontFamily: 'monospace', fontSize: '0.85rem' }} />
                    <label style={{ display: 'flex', alignItems: 'center', gap: 8, color: 'var(--color-text-secondary)', fontSize: '0.8rem', cursor: 'pointer', marginTop: 4 }}>
                      <input type="checkbox" checked={tc.isHidden} onChange={e => { const nc = [...newTestCases]; nc[idx].isHidden = e.target.checked; setNewTestCases(nc) }} />
                      Hidden Test Case (Used for final evaluation only)
                    </label>
                  </div>
                ))}
              </div>

              <div style={{ borderTop: '1px solid var(--color-border)', margin: '12px 0' }} />

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div>
                  <label style={{ display: 'block', marginBottom: 8, color: 'var(--color-text-secondary)', fontSize: '0.85rem' }}>Python Template</label>
                  <textarea value={newTemplates.python} onChange={e => setNewTemplates({ ...newTemplates, python: e.target.value })} placeholder="def solve(...):" rows={4} style={{ width: '100%', padding: '10px 12px', borderRadius: 8, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: 'white', fontFamily: 'monospace', fontSize: '0.85rem' }} />
                </div>
                <div>
                  <label style={{ display: 'block', marginBottom: 8, color: 'var(--color-text-secondary)', fontSize: '0.85rem' }}>JavaScript Template</label>
                  <textarea value={newTemplates.javascript} onChange={e => setNewTemplates({ ...newTemplates, javascript: e.target.value })} placeholder="function solve(...) { }" rows={4} style={{ width: '100%', padding: '10px 12px', borderRadius: 8, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: 'white', fontFamily: 'monospace', fontSize: '0.85rem' }} />
                </div>
                <div>
                  <label style={{ display: 'block', marginBottom: 8, color: 'var(--color-text-secondary)', fontSize: '0.85rem' }}>C++ Template</label>
                  <textarea value={newTemplates.cpp} onChange={e => setNewTemplates({ ...newTemplates, cpp: e.target.value })} placeholder="#include <bits/stdc++.h>" rows={4} style={{ width: '100%', padding: '10px 12px', borderRadius: 8, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: 'white', fontFamily: 'monospace', fontSize: '0.85rem' }} />
                </div>
                <div>
                  <label style={{ display: 'block', marginBottom: 8, color: 'var(--color-text-secondary)', fontSize: '0.85rem' }}>Java Template</label>
                  <textarea value={newTemplates.java} onChange={e => setNewTemplates({ ...newTemplates, java: e.target.value })} placeholder="public class Solution { }" rows={4} style={{ width: '100%', padding: '10px 12px', borderRadius: 8, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.1)', color: 'white', fontFamily: 'monospace', fontSize: '0.85rem' }} />
                </div>
              </div>

            </div>
            
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 12, marginTop: 24 }}>
              <button onClick={() => setShowModal(false)} style={{ background: 'transparent', color: 'white', border: '1px solid var(--color-border)', padding: '8px 16px', borderRadius: 8, cursor: 'pointer' }}>Cancel</button>
              <button onClick={handleSaveProblem} style={{ background: '#3B82F6', color: 'white', border: 'none', padding: '8px 16px', borderRadius: 8, cursor: 'pointer', fontWeight: 600 }}>Save Problem</button>
            </div>
          </div>
        </div>
      )}

    </div>
  )
}
