import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../contexts/AuthContext'

const API_URL = import.meta.env.VITE_API_URL || '/api/v1'

export default function ProfilePage() {
  const { user, signOut } = useAuth()
  const [activeTab, setActiveTab] = useState<'submissions' | 'stats' | 'settings'>('submissions')
  const [stats, setStats] = useState<any>(null)
  const [submissions, setSubmissions] = useState<any[]>([])

  useEffect(() => {
    if (user) {
      user.getIdToken().then(token => {
        // Fetch User Stats
        fetch(`${API_URL}/users/profile`, { headers: { 'Authorization': `Bearer ${token}` } })
          .then(res => res.json())
          .then(data => setStats(data))
          .catch(console.error)

        // Fetch User Submissions
        fetch(`${API_URL}/users/submissions`, { headers: { 'Authorization': `Bearer ${token}` } })
          .then(res => res.json())
          .then(data => setSubmissions(data))
          .catch(console.error)
      })
    }
  }, [user])

  if (!user) {
    return <div style={{ color: 'white', padding: 40, textAlign: 'center' }}>Please sign in to view your profile.</div>
  }

  // Ring calculations
  const totalSolved = stats?.problemsSolved || 0;
  const totalProblems = (stats?.totalByDifficulty?.Easy || 0) + (stats?.totalByDifficulty?.Medium || 0) + (stats?.totalByDifficulty?.Hard || 0) || 1;
  const solvePercent = (totalSolved / totalProblems) * 100;
  
  // Heatmap generation (mock data for visual aesthetics, since actual data per day is missing)
  const heatmapDays = Array.from({ length: 180 }).map((_, i) => {
    // Generate some random activity
    const activity = Math.random() > 0.7 ? Math.floor(Math.random() * 4) + 1 : 0;
    return activity;
  });

  return (
    <div style={{ minHeight: '100vh', background: 'var(--color-ink)' }}>
      {/* Navbar (simplified for profile) */}
      <nav style={{ height: 60, borderBottom: '1px solid rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', padding: '0 24px', background: 'rgba(11,16,32,0.8)', backdropFilter: 'blur(20px)', position: 'sticky', top: 0, zIndex: 50 }}>
        <Link to="/problems" style={{ color: '#60A5FA', textDecoration: 'none', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6, transition: 'color 0.2s' }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
          Back to Problems
        </Link>
      </nav>

      <main style={{ maxWidth: 1100, margin: '0 auto', padding: '40px 24px', display: 'flex', gap: 32, alignItems: 'flex-start' }}>
        
        {/* LEFT PANE: User Info */}
        <div style={{ width: 300, background: 'var(--color-surface-1)', borderRadius: 16, border: '1px solid var(--color-border)', padding: 24, display: 'flex', flexDirection: 'column', position: 'sticky', top: 100 }}>
          <div style={{ display: 'flex', gap: 16, alignItems: 'center', marginBottom: 24 }}>
            <div style={{ width: 80, height: 80, borderRadius: 16, background: 'linear-gradient(135deg, #3B82F6, #10B981)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem', fontWeight: 700, color: 'white', boxShadow: '0 8px 32px rgba(59,130,246,0.3)' }}>
              {user.displayName?.[0]?.toUpperCase() || user.email?.[0]?.toUpperCase() || 'U'}
            </div>
            <div>
              <h1 style={{ color: 'white', fontSize: '1.4rem', marginBottom: 4, fontWeight: 700 }}>{user.displayName || user.email?.split('@')[0]}</h1>
              <div style={{ color: 'var(--color-text-tertiary)', fontSize: '0.9rem' }}>{user.email}</div>
            </div>
          </div>

          <div style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
              <span style={{ color: 'var(--color-text-secondary)', fontSize: '0.95rem' }}>Rank</span>
              <span style={{ color: 'white', fontWeight: 600 }}>{stats?.rank ? stats.rank.toLocaleString() : 'N/A'}</span>
            </div>
          </div>

          <button style={{ background: 'rgba(59,130,246,0.1)', border: '1px solid rgba(59,130,246,0.2)', color: '#60A5FA', padding: '10px 0', borderRadius: 8, cursor: 'pointer', fontSize: '0.9rem', fontWeight: 600, transition: 'all 0.2s', width: '100%', marginBottom: 12 }}>
            Edit Profile
          </button>
          
          <button onClick={() => signOut()} style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', color: 'var(--color-text-secondary)', padding: '10px 0', borderRadius: 8, cursor: 'pointer', fontSize: '0.9rem', fontWeight: 600, transition: 'all 0.2s', width: '100%' }}>
            Sign Out
          </button>
        </div>

        {/* RIGHT PANE: Stats & Heatmap */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 24 }}>
          
          {/* Top Row: Solved Ring & General Stats */}
          <div style={{ display: 'flex', gap: 24 }}>
            {/* Solved Ring Card */}
            <div style={{ flex: 1, background: 'var(--color-surface-1)', borderRadius: 16, border: '1px solid var(--color-border)', padding: 24 }}>
              <h3 style={{ color: 'var(--color-text-secondary)', fontSize: '0.9rem', fontWeight: 600, marginBottom: 20 }}>Solved Problems</h3>
              <div style={{ display: 'flex', alignItems: 'center', gap: 32 }}>
                
                {/* SVG Ring */}
                <div style={{ position: 'relative', width: 120, height: 120 }}>
                  <svg width="120" height="120" viewBox="0 0 120 120">
                    <circle cx="60" cy="60" r="54" fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="8" />
                    {totalSolved > 0 && (
                      <circle cx="60" cy="60" r="54" fill="none" stroke="#F59E0B" strokeWidth="8" strokeDasharray={`${solvePercent * 3.39} 339`} strokeLinecap="round" transform="rotate(-90 60 60)" />
                    )}
                  </svg>
                  <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
                    <span style={{ fontSize: '1.8rem', fontWeight: 700, color: 'white', lineHeight: 1.1 }}>{totalSolved}</span>
                    <span style={{ fontSize: '0.75rem', color: 'var(--color-text-tertiary)' }}>/ {totalProblems}</span>
                  </div>
                </div>

                {/* Difficulty Bars */}
                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 16 }}>
                  {[{ label: 'Easy', color: '#10B981', count: stats?.difficultyBreakdown?.Easy || 0, total: stats?.totalByDifficulty?.Easy || 1 },
                    { label: 'Medium', color: '#F59E0B', count: stats?.difficultyBreakdown?.Medium || 0, total: stats?.totalByDifficulty?.Medium || 1 },
                    { label: 'Hard', color: '#EF4444', count: stats?.difficultyBreakdown?.Hard || 0, total: stats?.totalByDifficulty?.Hard || 1 }
                  ].map(d => (
                    <div key={d.label}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6, fontSize: '0.85rem' }}>
                        <span style={{ color: d.color }}>{d.label}</span>
                        <span style={{ color: 'white', fontWeight: 600 }}>{d.count} <span style={{ color: 'var(--color-text-tertiary)', fontWeight: 400 }}>/ {d.total}</span></span>
                      </div>
                      <div style={{ height: 6, background: 'rgba(255,255,255,0.05)', borderRadius: 3, overflow: 'hidden' }}>
                        <div style={{ height: '100%', background: d.color, width: `${Math.min(100, (d.count / d.total) * 100)}%`, borderRadius: 3 }} />
                      </div>
                    </div>
                  ))}
                </div>

              </div>
            </div>

            {/* General Stats Card */}
            <div style={{ flex: 1, background: 'var(--color-surface-1)', borderRadius: 16, border: '1px solid var(--color-border)', padding: 24 }}>
               <h3 style={{ color: 'var(--color-text-secondary)', fontSize: '0.9rem', fontWeight: 600, marginBottom: 20 }}>Stats</h3>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
                  <div>
                    <div style={{ fontSize: '0.8rem', color: 'var(--color-text-tertiary)', marginBottom: 4 }}>Acceptance Rate</div>
                    <div style={{ fontSize: '1.4rem', color: 'white', fontWeight: 700 }}>{stats?.acceptanceRate || 0}%</div>
                  </div>
                  <div>
                    <div style={{ fontSize: '0.8rem', color: 'var(--color-text-tertiary)', marginBottom: 4 }}>Total Submissions</div>
                    <div style={{ fontSize: '1.4rem', color: 'white', fontWeight: 700 }}>{stats?.totalSubmissions || 0}</div>
                  </div>
               </div>
            </div>
          </div>

          {/* Activity Heatmap */}
          <div style={{ background: 'var(--color-surface-1)', borderRadius: 16, border: '1px solid var(--color-border)', padding: 24 }}>
            <h3 style={{ color: 'var(--color-text-secondary)', fontSize: '0.9rem', fontWeight: 600, marginBottom: 20 }}>180 Days of Activity</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, height: 90, alignContent: 'start', flexDirection: 'column' }}>
              {heatmapDays.map((activity, i) => {
                const colors = ['rgba(255,255,255,0.05)', '#0e4429', '#006d32', '#26a641', '#39d353']; // Github style colors
                return (
                  <div key={i} style={{ width: 12, height: 12, borderRadius: 2, background: colors[activity], transition: 'transform 0.1s' }} />
                )
              })}
            </div>
            <div style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 6, marginTop: 12, fontSize: '0.75rem', color: 'var(--color-text-tertiary)' }}>
              Less
              <div style={{ width: 12, height: 12, borderRadius: 2, background: 'rgba(255,255,255,0.05)' }} />
              <div style={{ width: 12, height: 12, borderRadius: 2, background: '#0e4429' }} />
              <div style={{ width: 12, height: 12, borderRadius: 2, background: '#006d32' }} />
              <div style={{ width: 12, height: 12, borderRadius: 2, background: '#26a641' }} />
              <div style={{ width: 12, height: 12, borderRadius: 2, background: '#39d353' }} />
              More
            </div>
          </div>

          {/* Recent Submissions */}
          <div style={{ background: 'var(--color-surface-1)', borderRadius: 16, border: '1px solid var(--color-border)', padding: '24px 0', overflow: 'hidden' }}>
            <h3 style={{ color: 'var(--color-text-secondary)', fontSize: '0.9rem', fontWeight: 600, marginBottom: 16, padding: '0 24px' }}>Recent Submissions</h3>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ background: 'rgba(0,0,0,0.2)', color: 'var(--color-text-secondary)', fontSize: '0.8rem' }}>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Time Submitted</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Problem</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Status</th>
                  <th style={{ padding: '12px 24px', fontWeight: 500 }}>Language</th>
                </tr>
              </thead>
              <tbody>
                {submissions.length === 0 && (
                  <tr>
                    <td colSpan={4} style={{ padding: '24px', textAlign: 'center', color: 'var(--color-text-tertiary)' }}>No recent submissions.</td>
                  </tr>
                )}
                {submissions.slice(0, 10).map(sub => (
                  <tr key={sub.id} style={{ borderTop: '1px solid var(--color-border)', color: 'white', fontSize: '0.85rem', transition: 'background 0.2s' }}>
                    <td style={{ padding: '16px 24px', color: 'var(--color-text-tertiary)' }}>{new Date(sub.createdAt).toLocaleString()}</td>
                    <td style={{ padding: '16px 24px', fontWeight: 500 }}>
                      <Link to={`/problems/${sub.problemId}`} style={{ color: '#60A5FA', textDecoration: 'none' }}>{sub.problem?.title || 'Unknown Problem'}</Link>
                    </td>
                    <td style={{ padding: '16px 24px' }}>
                      <span style={{ 
                        color: sub.status === 'ACCEPTED' ? '#10B981' : sub.status === 'WRONG_ANSWER' ? '#EF4444' : '#F59E0B', 
                        fontWeight: 600 
                      }}>
                        {sub.status.replace(/_/g, ' ')}
                      </span>
                    </td>
                    <td style={{ padding: '16px 24px' }}>
                      <span style={{ background: 'rgba(255,255,255,0.05)', padding: '4px 8px', borderRadius: 4, fontSize: '0.75rem', color: 'var(--color-text-secondary)' }}>{sub.language}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </div>
      </main>
    </div>
  )
}
